function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}function btn(label,route,primary=false,i=''){return `<a class="btn ${primary?'primary':''}" href="#${route}">${i?icon(i):''}${label}</a>`}function head(title,sub,actions='',eye=''){return `<div class="page-head"><div>${eye?`<div class="eyebrow">${eye}</div>`:''}<h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="buttons">${actions}</div></div>`}function bar(k){return `<div class="bar-row"><div class="bar" role="progressbar" aria-label="${esc(k.code)} evidence coverage" aria-valuenow="${progress(k)}" aria-valuemin="0" aria-valuemax="100"><div class="fill ${state(k)}" style="width:${progress(k)}%"></div></div><span class="percent">${progress(k)}%</span></div>`}function row(k){return `<a href="#ksb/${k.code}" class="ksb-row"><div class="row-top">${code(k.code)}<span class="ksb-title">${k.title}</span><span class="status ${state(k)}">${stateText(state(k))}</span></div>${bar(k)}</a>`}function activity(l){return `<div class="activity"><div class="activity-icon">${icon('file')}</div><div class="activity-info"><div class="activity-title">${esc(l.title)}</div><div class="activity-meta">${date(l.date)} · ${esc(l.project)} · ${l.files.length} evidence reference${l.files.length!==1?'s':''}</div></div><div class="chips">${l.codes.slice(0,3).map(code).join('')}</div><span class="hour">${l.hours}h</span></div>`}
function dashboard(){return head('You’re building a strong story, Alex.','Everyday work, meaningful learning. Here’s how your evidence is taking shape.',btn('Generate report','report',false,'report')+btn('Log today’s work','log',true,'plus'),'YOUR APPRENTICESHIP, AT A GLANCE')+`<div class="stats">${[['Learning activities',logs.length,'Across your apprenticeship','log'],['Off-the-job hours',totalHours(),'<em>Learning captured</em> and ready to review','clock'],['KSBs with strong evidence',ksbs.filter(k=>state(k)==='strong').length,'Well-supported by your activities','check'],['KSBs needing attention',ksbs.filter(k=>['attention','empty'].includes(state(k))).length,'A little focus makes a difference','target']].map(([t,v,n,i])=>`<div class="stat"><div class="stat-top">${t}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${v}<span>${i==='clock'?'hrs':i==='check'?'of 10':''}</span></div><div class="stat-note">${n}</div></div>`).join('')}</div><div class="grid"><section class="card"><div class="card-head"><div><h2>KSB Progress</h2><p>Your evidence against your own apprenticeship requirements.</p></div><span class="badge">10 requirements</span></div><div class="tabs" role="tablist">${['All','Knowledge','Skills','Behaviours'].map(t=>`<button class="tab ${filter===t?'active':''}" role="tab" aria-selected="${filter===t}" data-filter="${t}">${t}</button>`).join('')}</div><div id="ksb-list">${ksbs.filter(k=>filter==='All'||k.code.startsWith({Knowledge:'K',Skills:'S',Behaviours:'B'}[filter])).map(row).join('')}</div><div class="legend">${[['#32a58d','Strong evidence'],['#5843dc','Progressing'],['#e3ac56','Needs attention'],['#d4d4df','No evidence yet']].map(([c,t])=>`<span><i style="background:${c}"></i>${t}</span>`).join('')}</div></section><div class="right-stack"><section class="journey"><h2>Your evidence coverage</h2><p style="text-align:left;margin-top:7px">A clearer picture, one day at a time.</p><div class="ring" style="--value:${avg()}"><div class="ring-content"><b>${avg()}%</b><small>overall coverage</small></div></div><p>You have evidence for <b>${ksbs.filter(k=>progress(k)>0).length} of 10 KSBs</b>.<br>Keep capturing the work you’re already doing.</p><div class="journey-meta"><span>Apprenticeship started</span><b>April 2026</b></div></section><section class="opportunity"><div class="icon-line">${icon('spark')}<span style="font-size:12px;font-weight:600">YOUR NEXT OPPORTUNITY</span></div><h3>Let your analysis do the talking.</h3><p>Present your latest findings to your team. It could add a new context to your evidence for S6.</p>${btn('Explore your evidence gaps','progress')}</section></div></div><section class="card recent"><div class="card-head"><div><h2>Recent activity</h2><p>The work behind your progress.</p></div><button class="text-link" data-action="history">View all activities</button></div>${logs.slice(0,3).map(activity).join('')}</section>`}
