function detailPage(id){const k=ksbs.find(k=>k.code===id);if(!k)return dashboard();const ls=mapped(k);return head(k.title,`${id} · ${id.startsWith('K')?'Knowledge':id.startsWith('S')?'Skill':'Behaviour'} · Data analyst apprenticeship`,btn('Back to dashboard','dashboard'),'KSB DETAIL')+`<div class="details-top"><section class="card"><div class="row-top">${code(k.code)}<span class="status ${state(k)}">${stateText(state(k))}</span></div><h2>Your evidence for ${k.code}</h2><p>Demonstrate ${k.title.toLowerCase()} through practical activities, reflection and supporting evidence across different contexts.</p><div class="detail-bar">${bar(k)}</div><div class="detail-meta"><span><b>${ls.length}</b> mapped activities</span><span>Latest evidence: <b>${ls.length?date(ls[0].date):'Not captured yet'}</b></span></div></section><section class="opportunity"><div class="icon-line">${icon('spark')}<h3 style="margin:0">A useful next step</h3></div><p>${progress(k)===0?'Try a small activity with your manager that lets you practise this requirement, then capture what you learned.':state(k)==='strong'?'You have a useful range of evidence. Keep adding your reflections and specific outcomes to support a review.':'You’ve mentioned this skill, but most of your evidence is similar. Try demonstrating it in a different context.'}</p>${btn('Log a new activity','log')}</section></div><section class="card"><div class="card-head"><div><h2>Evidence timeline</h2><p>Activities you have reviewed and mapped to this requirement.</p></div><span class="badge">${ls.length} activities</span></div>${ls.length?`<div class="timeline">${ls.map(l=>`<article class="timeline-item"><div class="timeline-date">${date(l.date)} · ${l.hours}h ${l.otj?'learning':''}</div><h3>${esc(l.title)}</h3><b>What you did</b><p>${esc(l.work)}</p><b>What you learned</b><p>${esc(l.learn)}</p><div class="evidence-list">${l.files.length?l.files.map(f=>`<span class="evidence-pill">${esc(f)}</span>`).join(''):'<span class="hint">No files attached — add work outputs when available.</span>'}</div><span class="status progressing">${l.added?'+5 coverage points':'Contributes to current coverage'}</span></article>`).join('')}</div>`:`<div class="empty-state"><h3>Your first piece of evidence starts here.</h3><p>There’s no activity mapped yet. Your next learning opportunity can change that.</p>${btn('Capture an activity','log',true)}</div>`}</section>`}
function progressPage(){return head('A little direction for your next step.','See what’s going well and where a new experience could strengthen your evidence.',btn('Log an activity','log',true,'plus'),'PROGRESS & GAPS')+`<div class="gap-grid">${[['Going well','A useful range of evidence to build on.',k=>state(k)==='strong'],['Needs more evidence','Keep developing depth and variety.',k=>['progressing','attention'].includes(state(k))],['Not covered yet','A starting point for your next opportunity.',k=>state(k)==='empty']].map(([t,p,fn])=>`<section class="card"><h2>${t} <span class="badge">${ksbs.filter(fn).length}</span></h2><p class="subtitle">${p}</p>${ksbs.filter(fn).map(row).join('')}</section>`).join('')}</div><div class="section-space"><h2>Suggested opportunities</h2><p class="subtitle" style="margin-bottom:20px">Practical ways to turn your next piece of work into useful learning.</p><div class="opportunities">${[['S6','Share your findings with your team','You have limited evidence for presenting information to stakeholders. If you present your current analysis to your team, log it afterwards and it may contribute towards S6.'],['K4','Explore the numbers behind a trend','Ask a colleague to walk through averages, variation and outliers in your latest sales dataset. Capture the principles you learned and the assumptions you checked.'],['S8','Try a statistical technique in context','Compare two regions using a simple statistical method, with guidance from your manager. Save your method, interpretation and limitations.'],['K3','Apply your privacy learning','Review a report before sharing it. Explain which personal fields you removed, why, and how you checked the intended audience.']].map(([id,t,p])=>`<section class="card"><div class="row-top">${code(id)}<span class="hint">Suggested learning opportunity</span></div><h3>${t}</h3><p class="subtitle" style="line-height:1.8;margin-bottom:18px">${p}</p>${btn('View requirement','ksb/'+id)} <button class="text-link" style="margin-left:15px" data-action="opportunity" data-id="${id}">Log this opportunity</button></section>`).join('')}</div></div>`}
function reportPage(){const ls=logs.filter(l=>l.date>=reportStart&&l.date<=reportEnd),hours=ls.filter(l=>l.otj).reduce((s,l)=>s+l.hours,0),ids=[...new Set(ls.flatMap(l=>l.codes))];return head('Your progress report, ready to review.','Your activity and learning, brought together without starting from scratch.',`<button class="btn" data-action="download">${icon('file')} Download report</button><button class="btn primary" data-action="print">${icon('report')} Print / save PDF</button>`,'GENERATED REPORT')+`<div class="card" style="margin-bottom:22px"><form id="period-form" class="buttons" style="justify-content:flex-start;flex-wrap:wrap"><div><label for="period-start">Reporting from</label><input id="period-start" type="date" value="${reportStart}" required></div><div><label for="period-end">Reporting to</label><input id="period-end" type="date" value="${reportEnd}" required></div><button class="btn" type="submit" style="align-self:flex-end">Generate progress report</button></form></div><article class="report" id="report-content"><div class="report-head"><div><div class="eyebrow">KS-BUDDY · APPRENTICESHIP RECORD</div><h1>Apprenticeship progress report</h1><p style="margin:0">Alex Johnson · Data analyst, Level 4<br>Northstar · ${date(reportStart)} – ${date(reportEnd)}</p></div><span class="badge" style="align-self:start">Draft for review</span></div><div class="report-summary"><div><b>${ls.length}</b>learning activities</div><div><b>${hours}h</b>off-the-job learning recorded</div><div><b>${ids.length} / 10</b>KSBs with mapped activity</div></div><h2>Summary of work completed</h2>${ls.length?`<p>During this reporting period, Alex recorded ${ls.length} activities across ${[...new Set(ls.map(l=>l.project.toLowerCase()))].map(esc).join(', ')}. The activities below provide a record of practical work, reflection and suggested evidence against apprenticeship requirements.</p><ul>${ls.map(l=>`<li><b>${esc(l.title)}</b> (${date(l.date)}): ${esc(l.work)}</li>`).join('')}</ul>`:'<p>No activities are recorded in this period. Choose dates that include your learning.</p>'}<h2>Key learning</h2><ul>${ls.map(l=>`<li>${esc(l.learn)}</li>`).join('')||'<li>No learning recorded in this period.</li>'}</ul><h2>KSBs evidenced</h2><p>Reviewed activity mappings indicate suggested evidence for the following requirements; they do not confirm achievement.</p><table><thead><tr><th>KSB</th><th>Requirement</th><th>Activities in period</th><th>Overall coverage</th></tr></thead><tbody>${ids.map(id=>{let k=ksbs.find(k=>k.code===id);return `<tr><td>${id}</td><td>${k.title}</td><td>${ls.filter(l=>l.codes.includes(id)).length}</td><td>${progress(k)}%</td></tr>`}).join('')}</tbody></table><h2>Off-the-job learning activities</h2><p>${hours} hours were marked as off-the-job learning. This is a record for provider review.</p><ul>${ls.filter(l=>l.otj).map(l=>`<li>${date(l.date)} · ${esc(l.title)} · ${l.hours} hours</li>`).join('')||'<li>No off-the-job learning in this period.</li>'}</ul><h2>Strongest areas</h2><p>${ksbs.filter(k=>state(k)==='strong').map(k=>`${k.code} (${k.title.toLowerCase()})`).join('; ')} have the strongest overall evidence coverage in the record.</p><h2>Development areas</h2><p>${ksbs.filter(k=>['attention','empty'].includes(state(k))).map(k=>`${k.code} (${k.title.toLowerCase()})`).join('; ')} would benefit from additional evidence. Present findings to the team and explore statistical methods with a colleague to broaden your learning.</p><h2>Evidence references</h2><ul>${ls.flatMap((l,i)=>l.files.map((f,j)=>`<li>REF-${String(i+1).padStart(2,'0')}.${j+1} · ${esc(f)} · ${date(l.date)} · ${l.codes.join(', ')}</li>`)).join('')||'<li>No evidence files referenced in this period.</li>'}</ul><div class="notice section-space">Generated from your recorded activities. Review wording, off-the-job learning eligibility and evidence references with your provider. Sample KSB descriptions are illustrative.</div></article>`}
function historyPage(){return head('Your everyday work, all in one place.','Activities you’ve captured and reviewed with Buddy.',btn('Log today’s work','log',true,'plus'),'ACTIVITY RECORD')+`<section class="card">${logs.map(l=>`<div style="padding:10px 0">${activity(l)}<p class="subtitle" style="margin:10px 0 14px 52px">${esc(l.learn)}</p><div class="evidence-list" style="margin-left:52px">${l.files.map(f=>`<span class="evidence-pill">${esc(f)}</span>`).join('')}</div></div>`).join('')}</section>`}
function render(){const path=(location.hash.slice(1)||'dashboard').split('/'),view=path[0];$('#nav').innerHTML=[['dashboard','Talk to Buddy','spark'],['log','Daily log','log'],['progress','Progress & gaps','progress'],['report','Reports','report'],['import','Import data','file']].map(([r,t,i])=>`<a href="#${r}" class="${view===r||r==='dashboard'&&['ksb','history'].includes(view)?'active':''}">${icon(i)}${t}</a>`).join('');$('#breadcrumb').innerHTML=`Workspace <span>/</span> ${{dashboard:'Talk to Buddy',log:'Daily log',analysis:'AI analysis',progress:'Progress & gaps',report:'Reports',ksb:'KSB detail',history:'Activity record',import:'Import data'}[view]||'Overview'}`;$('#app').innerHTML=({dashboard,log:logPage,analysis:analysisPage,progress:progressPage,report:reportPage,history:historyPage,import:importPage}[view]||(()=>detailPage(path[1])))();window.scrollTo({top:0,behavior:'instant'});bindForms()}
function syncAnalysis(){if($('#summary')){draft.summary=$('#summary').textContent;draft.learn=$('#learning').textContent}if(editing!==null&&$('#reason-'+editing))suggestions[editing].reason=$('#reason-'+editing).value}
function bindForms(){if($('#log-form'))$('#log-form').onsubmit=e=>{e.preventDefault();const files=[...$('#files').files];draft={work:$('#work').value.trim(),date:$('#date').value,hours:Number($('#hours').value),project:$('#project').value,otj:$('#otj').checked,files:files.length?files.map(f=>f.name):draft?.files||[]};if(draft.work.length<20)return;$('#app').innerHTML=`<div class="loading"><div class="spinner"></div><h1>Finding the learning in your day.</h1><p class="muted">Organising your work into suggestions you can review.</p><div class="steps"><span>Capture ✓</span><span>Analyse your activity</span><span>Suggest KSB mappings</span></div><p class="hint section-space">Simulated analysis · no AI service is called</p></div>`;setTimeout(()=>{makeSuggestions();location.hash='analysis'},1500)};if($('#period-form'))$('#period-form').onsubmit=e=>{e.preventDefault();const start=$('#period-start').value,end=$('#period-end').value;if(start>end){toast('Choose an end date after the start date.');return}reportStart=start;reportEnd=end;render();toast('Progress report generated for your selected period.')};if($('#analysis-files'))$('#analysis-files').onchange=e=>{draft.files=[...new Set([...draft.files,...[...e.target.files].map(f=>f.name)])];syncAnalysis();render();toast('Evidence file references added.')};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-filter]');if(!b)return;if(b.dataset.filter){filter=b.dataset.filter;render();return}const a=b.dataset.action,i=Number(b.dataset.index);if(location.hash==='#analysis')syncAnalysis();if(a==='history')location.hash='history';if(a==='example'){$('#work').value=example;$('#work').focus()}if(a==='accept'){suggestions[i].accepted=!suggestions[i].accepted;render()}if(a==='accept-all'){suggestions.forEach(s=>s.accepted=true);render()}if(a==='remove'){suggestions.splice(i,1);editing=null;render()}if(a==='edit'){editing=editing===i?null:i;render();if(editing!==null)$('#reason-'+i).focus()}if(a==='save'){syncAnalysis();const selected=suggestions.filter(s=>s.accepted);saveRecord(selected)}if(a==='opportunity'){const k=ksbs.find(k=>k.code===b.dataset.id);draft={work:'',project:k.code==='S6'?'Communication':'Training',hours:1.5,date:'2026-10-03',otj:true,files:[]};location.hash='log';toast('Capture what you did and learned for '+k.code+'.')}if(a==='print')window.print();if(a==='download'){const txt=$('#report-content').innerText;const blob=new Blob([txt],{type:'text/plain;charset=utf-8'});const u=URL.createObjectURL(blob),el=document.createElement('a');el.href=u;el.download=`ks-buddy-progress-report-${reportStart}-to-${reportEnd}.txt`;el.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('Your progress report has been downloaded.')}});window.addEventListener('hashchange',render);
let savedRecords=[],demoMode=false,storageError='',buddyMessages=[],buddyBusy=false;
const originalDashboard=dashboard;
function applyRecords(){logs=demoMode?[...savedRecords,...seedLogs.map(l=>({...l,demo:true}))]:[...savedRecords];ksbs=seedK.map(k=>({...k,base:demoMode?k.base:0}));}
async function loadRecords(){try{const r=await fetch('/api/records');if(!r.ok)throw Error();savedRecords=await r.json();applyRecords();storageError='';render()}catch{storageError='Your saved record is unavailable. You can still write your day; saving will be available when the local workspace reconnects.';render()}}
async function saveRecord(selected){syncAnalysis();const record={...draft,work:draft.summary,learn:draft.learn,codes:selected.map(s=>s.id),mappingReasons:selected.map(s=>({code:s.id,reason:s.reason})),added:true,id:crypto.randomUUID()};const b=document.querySelector('[data-action="save"]');if(b)b.disabled=true;try{const r=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(record)});if(!r.ok)throw Error();savedRecords.unshift(record);applyRecords();draft=null;suggestions=[];editing=null;buddyMessages=[];location.hash='dashboard';toast('Saved to your record. Your trackers and report are up to date.')}catch{if(b)b.disabled=false;toast('Couldn’t save just now. Your entry is still here — please try again.')}}
dashboard=function(){const own=logs.filter(l=>!l.demo);return `<section class="buddy-home"><div class="buddy-welcome"><div class="eyebrow">YOUR DAY. YOUR LEARNING.</div><h1>Hey Alex. How was your day?</h1><p>Talk to Buddy. We’ll find the learning together.</p></div><div class="buddy-layout"><div class="buddy-conversation"><div class="buddy-greeting"><span class="buddy-symbol">${icon('spark')}</span><div><b>Buddy</b><p>What have you been working on today? Tell me the messy version — what you tried, what clicked, or what you’re still figuring out.</p></div></div><div id="messages">${buddyMessages.map(m=>`<div class="chat-message ${m.who}"><span>${m.who==='you'?'You':'Buddy'}</span><p>${esc(m.text)}</p></div>`).join('')}</div>${buddyBusy?'<div class="buddy-thinking">Buddy is finding the learning…</div>':''}<form id="buddy-form"><label class="sr-only" for="buddy-text">Tell Buddy about your day</label><textarea id="buddy-text" required minlength="20" placeholder="Today I worked on…" rows="4">${esc(draft?.work||'')}</textarea><div class="composer-bottom"><span>Write naturally. A few sentences is plenty.</span><button class="btn primary" type="submit" ${buddyBusy?'disabled':''}>Talk to Buddy ${icon('spark')}</button></div><details class="capture-extras"><summary>Add time, date or an evidence reference</summary><div class="form-grid"><div><label for="buddy-hours">Learning time (hours)</label><input id="buddy-hours" type="number" min="0.25" max="24" step="0.25" value="1"></div><div><label for="buddy-date">Date</label><input id="buddy-date" type="date" value="2026-10-03" max="2026-10-03"></div><div><label for="buddy-project">Category</label><select id="buddy-project"><option>Reporting</option><option>Training</option><option>Communication</option><option>Other</option></select></div></div><label class="checkline"><input id="buddy-otj" type="checkbox">This was off-the-job learning</label><label for="buddy-files" style="margin-top:18px">Evidence files (filename references only)</label><input id="buddy-files" type="file" multiple></details></form><div class="conversation-note">${icon('spark')} Prototype Buddy uses simulated suggestions. You review every mapping.</div>${storageError?`<div class="notice">${storageError}</div>`:''}${draft?.summary?`<div class="buddy-review"><h3>I’ve found ${suggestions.length} possible connections.</h3><p>Let’s check the learning and KSB suggestions before saving anything.</p>${btn('Review with Buddy','analysis',true)}</div>`:''}</div><aside class="buddy-trackers"><div class="trackers-head"><h2>Your learning, taking shape</h2><span>${demoMode?'Includes sample activities':'Your saved activities'}</span></div><div class="simple-metrics"><div><b>${own.length}</b><span>activities captured</span></div><div><b>${own.filter(l=>l.otj).reduce((s,l)=>s+l.hours,0)}<em>h</em></b><span>off-the-job learning</span></div></div><div class="coverage-inline"><div><span>Evidence coverage</span><b>${avg()}%</b></div><div class="bar"><div class="fill" style="width:${avg()}%"></div></div><small>${ksbs.filter(k=>progress(k)>0).length} of 10 requirements have some evidence</small></div><div class="compact-ksbs">${ksbs.slice(0,6).map(k=>`<a href="#ksb/${k.code}"><div>${code(k.code)}<span>${k.title}</span></div>${bar(k)}</a>`).join('')}</div><a class="text-link" href="#progress">Explore all requirements & gaps</a><div class="tracker-guidance"><h3>${own.length?'Keep the story growing.':'Your first chat starts your record.'}</h3><p>${own.length?'A new context or a reflection can add depth to your evidence.':'Once you review and save a conversation, your trackers will update here.'}</p></div><label class="checkline demo-switch"><input id="demo-switch" type="checkbox" ${demoMode?'checked':''}> Show example data</label><small>Sample activities stay separate from what you create.</small></aside></div><section class="buddy-recent"><div class="card-head"><h2>What you’ve been learning</h2><a class="text-link" href="#history">Your activity record</a></div>${own.length?own.slice(0,3).map(activity).join(''):'<p class="muted">Your saved conversations will appear here. Tell Buddy about today to begin.</p>'}</section></section>`};
const originalBind=bindForms;bindForms=function(){originalBind();if($('#demo-switch'))$('#demo-switch').onchange=e=>{demoMode=e.target.checked;applyRecords();render()};if($('#buddy-form'))$('#buddy-form').onsubmit=e=>{e.preventDefault();const text=$('#buddy-text').value.trim();if(text.length<20||buddyBusy)return;draft={work:text,date:$('#buddy-date').value,hours:Number($('#buddy-hours').value),otj:$('#buddy-otj').checked,project:$('#buddy-project').value,files:[...$('#buddy-files').files].map(f=>f.name)};buddyMessages.push({who:'you',text});buddyBusy=true;render();setTimeout(()=>{makeSuggestions();buddyBusy=false;buddyMessages.push({who:'buddy',text:`Thanks — I’ve picked out ${suggestions.length} possible KSB connections from what you described. What did you learn or understand better? You can add that reflection when we review your record.`});render()},900)}};

let importItems=[],importProblem='';
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('The CSV has an unclosed quote.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);const headers=rows.shift()?.map(x=>x.trim().toLowerCase().replace(/^\uFEFF/,''))||[];return rows.map(values=>Object.fromEntries(headers.map((h,i)=>[h,values[i]||''])))}
function normaliseImport(records){if(!Array.isArray(records)||!records.length)throw Error('No activity rows were found.');if(records.length>200)throw Error('Please import up to 200 activities at a time.');return records.map((r,i)=>{const pick=(...keys)=>{for(const k of keys)if(r[k]!==undefined&&r[k]!==null)return r[k];return ''};const work=String(pick('work','description','activity','notes','text')).trim();if(!work)throw Error(`Row ${i+1}: add a work, description, activity, notes or text field.`);const d=String(pick('date','activity_date')).slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||Number.isNaN(Date.parse(d)))throw Error(`Row ${i+1}: date must use YYYY-MM-DD.`);const hours=Number(pick('hours','time_spent','learning_hours')||0);if(!Number.isFinite(hours)||hours<0||hours>24)throw Error(`Row ${i+1}: hours must be between 0 and 24.`);let c=pick('codes','ksbs','ksb_codes');c=Array.isArray(c)?c:String(c).split(/[;,|\s]+/);c=c.filter(Boolean);if(c.some(id=>!seedK.some(k=>k.code===id)))throw Error(`Row ${i+1}: a KSB code is outside the sample standard.`);const f=pick('files','evidence','attachments');return {id:crypto.randomUUID(),work,summary:work,title:String(pick('title','name')||work.split(/[.!?]/)[0].slice(0,75)),learn:String(pick('learn','learning','reflection')||'Reflection not supplied — add learning context when reviewing this activity.'),date:d,hours,otj:['true','yes','1'].includes(String(pick('otj','off_the_job')).toLowerCase()),codes:c,files:Array.isArray(f)?f:String(f).split(/[;|]/).filter(Boolean),project:String(pick('project','category')||'Imported activity'),added:true,source:'File import'}})}
function importPage(){return `<div class="narrow">${head('Bring your work into Buddy.','Import activities from another tool, then review what belongs in your record.','','IMPORT DATA')}<section class="import-surface"><h2>Choose a CSV or JSON export</h2><p class="muted">Use an export from the app you’re working in. Buddy can read activity descriptions, learning, dates, hours, KSB codes and evidence references.</p><label for="import-file">Activity data file</label><input id="import-file" type="file" accept=".csv,.json,text/csv,application/json"><p class="hint">Required: date and work (or description). Optional: learning, hours, project, otj, codes, evidence. Dates: YYYY-MM-DD. Codes: K1;S3. Evidence: filenames or references, not uploaded files.</p><button class="text-link" data-import="template">Download an example CSV</button>${importProblem?`<p class="error" role="alert">${esc(importProblem)}</p>`:''}</section>${importItems.length?`<section class="section-space"><h2>Review ${importItems.length} imported activities</h2><p class="subtitle">Only checked rows will be saved. Imported KSB mappings remain suggestions for provider review.</p>${importItems.map((r,i)=>`<div class="import-row"><label class="checkline"><input type="checkbox" data-import-row="${i}" checked><b>${esc(r.title)}</b></label><p class="hint">${date(r.date)} · ${r.hours}h · ${esc(r.project)}${r.otj?' · off-the-job learning':''}</p><p>${esc(r.work)}</p><p class="hint">Learning: ${esc(r.learn)}</p><div class="chips">${r.codes.length?r.codes.map(code).join(''):'<span class="hint">No KSB mappings supplied</span>'}</div></div>`).join('')}<button class="btn primary" data-import="save">Save selected activities</button></section>`:''}<div class="notice section-space">This import reads a file you choose. A direct live connection needs the name of the source app and the data you want to sync.</div></div>`}
const bindWithBuddy=bindForms;bindForms=function(){bindWithBuddy();if($('#import-file'))$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Please use a file smaller than 2 MB.');const t=await f.text(),parsed=f.name.toLowerCase().endsWith('.json')?JSON.parse(t):parseCSV(t);importItems=normaliseImport(Array.isArray(parsed)?parsed:parsed.activities||parsed.records);importProblem='';render()}catch(err){importItems=[];importProblem=err.message;render()}}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-import]');if(!b)return;if(b.dataset.import==='template'){const csv='date,work,learning,hours,project,otj,codes,evidence\n2026-10-03,"Compared sales and finance reports","Learned how cut-off dates affect reporting",1.5,Reporting,true,K1;S3,report.pbix\n';const u=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=u;a.download='ks-buddy-import-example.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}if(b.dataset.import==='save'){const selected=[...document.querySelectorAll('[data-import-row]:checked')].map(el=>importItems[Number(el.dataset.importRow)]);if(!selected.length){toast('Choose at least one activity to import.');return}b.disabled=true;let count=0;try{for(const item of selected){const r=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});if(!r.ok)throw Error();count++;importItems=importItems.filter(x=>x.id!==item.id)}await loadRecords();location.hash='dashboard';toast(`${count} imported activities saved. Your trackers are updated.`)}catch{importProblem=`${count} activities saved. The remaining rows are still available; try saving again.`;await loadRecords();render()}}});
render();loadRecords();
